// An ArgumentParser faithful to argparse for a parser built from optional
// arguments only — the shape the source script uses.

import { ArgumentError, ArgumentParserError } from './errors.mjs';
import { formatUsage, formatHelp } from './formatter.mjs';
import { SystemExit } from '../python/errors.mjs';
import { reprStr } from '../python/repr.mjs';
import { writeStdout, writeStderr } from '../python/sys.mjs';

// A token that merely looks like a negative number is treated as a value, not
// an option — provided no option string itself looks numeric.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor(spec) {
    Object.assign(this, spec);
  }

  // How argparse names an action in error messages: every option string it
  // answers to, joined by slashes.
  get name() {
    return this.optionStrings.join('/');
  }
}

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog;
    this.actions = [];
    this.optionMap = new Map();
    if (addHelp) {
      this.addAction({
        optionStrings: ['-h', '--help'],
        dest: null,
        metavar: null,
        type: null,
        required: false,
        takesValue: false,
        help: 'show this help message and exit',
        isHelp: true,
      });
    }
  }

  addAction(spec) {
    const action = new Action(spec);
    this.actions.push(action);
    for (const option of action.optionStrings) this.optionMap.set(option, action);
    return action;
  }

  // add_argument for a single long option, e.g. ('--a', {type: INT_TYPE}).
  addArgument(optionString, { type, required = false, help = null } = {}) {
    const dest = optionString.replace(/^--?/, '').replace(/-/g, '_');
    return this.addAction({
      optionStrings: [optionString],
      dest,
      metavar: dest.toUpperCase(),
      type,
      required,
      takesValue: true,
      help,
      isHelp: false,
    });
  }

  // Whether a raw token should be read as an option, a plain value, or the
  // "--" end-of-options marker.
  classifyToken(token) {
    if (token === '') return 'value';
    if (!token.startsWith('-')) return 'value';
    if (token === '-') return 'value';
    if (token === '--') return 'separator';
    if (NEGATIVE_NUMBER.test(token)) return 'value';
    if (token.includes(' ')) return 'value';
    return 'option';
  }

  // Long options may be abbreviated to any unambiguous prefix.
  matchPrefix(prefix) {
    const matches = [];
    for (const [option, action] of this.optionMap) {
      if (option.startsWith('--') && option.startsWith(prefix)) matches.push({ option, action });
    }
    if (matches.length === 0) return null;
    const distinct = new Set(matches.map((entry) => entry.action));
    if (distinct.size > 1) {
      const names = matches.map((entry) => entry.option).join(', ');
      throw new ArgumentParserError(`ambiguous option: ${prefix} could match ${names}`);
    }
    return matches[0].action;
  }

  // Splits one option token into the action it names, any value attached with
  // "=" or packed after a short flag, and the remainder of a short cluster.
  splitOption(token) {
    const exact = this.optionMap.get(token);
    if (exact) return { action: exact, explicit: null, rest: null };

    if (token.startsWith('--')) {
      const separatorAt = token.indexOf('=');
      if (separatorAt > -1) {
        const head = token.slice(0, separatorAt);
        const action = this.optionMap.get(head) ?? this.matchPrefix(head);
        if (!action) return { action: null };
        return { action, explicit: token.slice(separatorAt + 1), rest: null };
      }
      const action = this.matchPrefix(token);
      return action ? { action, explicit: null, rest: null } : { action: null };
    }

    // Single dash: peel the two-character flag off the front of the cluster.
    const head = token.slice(0, 2);
    const action = this.optionMap.get(head);
    if (!action) return { action: null };
    const tail = token.slice(2);
    if (action.takesValue) return { action, explicit: tail === '' ? null : tail, rest: null };
    return { action, explicit: null, rest: tail === '' ? null : `-${tail}` };
  }

  convert(action, text) {
    const value = action.type.convert(text);
    if (value === null) {
      throw new ArgumentError(action.name, `invalid ${action.type.name} value: ${reprStr(text)}`);
    }
    return value;
  }

  // Consumes the option token at `index`, returning the next index to read.
  consumeOption(argv, index, namespace, seen, extras) {
    const token = argv[index];
    let pending = token;

    while (pending !== null) {
      const { action, explicit, rest } = this.splitOption(pending);
      if (!action) {
        // Unknown options are collected whole and reported after parsing.
        extras.push(token);
        return index + 1;
      }

      if (action.takesValue) {
        if (explicit !== null) {
          namespace[action.dest] = this.convert(action, explicit);
          seen.add(action);
          return index + 1;
        }
        const next = index + 1 < argv.length ? argv[index + 1] : null;
        if (next === null || this.classifyToken(next) !== 'value') {
          throw new ArgumentError(action.name, 'expected one argument');
        }
        namespace[action.dest] = this.convert(action, next);
        seen.add(action);
        return index + 2;
      }

      if (explicit !== null) {
        throw new ArgumentError(action.name, `ignored explicit argument ${reprStr(explicit)}`);
      }
      // Flags fire the moment they are reached, before any later token — and
      // before the required-argument check.
      if (action.isHelp) this.printHelpAndExit();
      pending = rest;
    }
    return index + 1;
  }

  parseArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.dest) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];
    let index = 0;
    let afterSeparator = false;

    while (index < argv.length) {
      const token = argv[index];
      if (afterSeparator) {
        extras.push(token);
        index += 1;
        continue;
      }
      const kind = this.classifyToken(token);
      if (kind === 'value') {
        extras.push(token);
        index += 1;
      } else if (kind === 'separator') {
        // With no positionals declared, "--" is never absorbed; it stays in
        // the leftovers and everything after it is a plain value.
        extras.push(token);
        afterSeparator = true;
        index += 1;
      } else {
        index = this.consumeOption(argv, index, namespace, seen, extras);
      }
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.name);
    if (missing.length > 0) {
      throw new ArgumentParserError(
        `the following arguments are required: ${missing.join(', ')}`,
      );
    }
    if (extras.length > 0) {
      throw new ArgumentParserError(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  printHelpAndExit() {
    writeStdout(formatHelp(this));
    throw new SystemExit(0);
  }

  // parser.error(): usage plus the message on stderr, then exit status 2.
  error(message) {
    writeStderr(formatUsage(this));
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }
}

export { ArgumentError, ArgumentParserError };

// Errors the argument parser raises internally.
//
// ArgumentError is attributed to a single action so the parser can prefix the
// message with that action's name; ArgumentParserError covers whole-parse
// failures such as missing or unrecognized arguments.

export class ArgumentError extends Error {
  constructor(actionName, detail) {
    super(`argument ${actionName}: ${detail}`);
    this.actionName = actionName;
    this.detail = detail;
  }
}

export class ArgumentParserError extends Error {
  constructor(detail) {
    super(detail);
    this.detail = detail;
  }
}
// Usage and help text layout, reproducing argparse's HelpFormatter output for
// a parser made up entirely of optional arguments.

const INDENT = '  ';
const MAX_HELP_POSITION = 24;

// In usage, an action appears under its first option string only, wrapped in
// brackets unless it is required.
function usageFragment(action) {
  const core = action.takesValue
    ? `${action.optionStrings[0]} ${action.metavar}`
    : action.optionStrings[0];
  return action.required ? core : `[${core}]`;
}

export function formatUsage(parser) {
  const fragments = parser.actions.map(usageFragment);
  return `usage: ${[parser.prog, ...fragments].join(' ')}\n`;
}

// In the options list every option string is shown, so the help action reads
// "-h, --help" rather than just "-h".
function helpInvocation(action) {
  if (!action.takesValue) return action.optionStrings.join(', ');
  return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
}

export function formatHelp(parser) {
  const invocations = parser.actions.map(helpInvocation);

  // argparse aligns help text one column past the widest invocation, capped so
  // a single long option cannot push every description off to the right.
  const widest = Math.max(0, ...invocations.map((text) => text.length + INDENT.length));
  const helpPosition = Math.min(widest + 2, MAX_HELP_POSITION);

  let out = formatUsage(parser);
  out += '\noptions:\n';
  parser.actions.forEach((action, index) => {
    const invocation = invocations[index];
    if (!action.help) {
      out += `${INDENT}${invocation}\n`;
      return;
    }
    const written = INDENT.length + invocation.length;
    // A description that would collide with its own invocation starts on the
    // next line instead; otherwise it is padded out to the help column.
    if (written + 2 > helpPosition) {
      out += `${INDENT}${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
    } else {
      out += `${INDENT}${invocation}${' '.repeat(helpPosition - written)}${action.help}\n`;
    }
  });
  return out;
}
// The `type=` callables the source script passes to add_argument.
//
// Each exposes the __name__ argparse quotes in "invalid <name> value: ..." and
// a convert() returning null to signal a conversion failure.

import { pyInt } from '../python/numbers.mjs';

export const STR = {
  name: 'str',
  // str(x) on a command-line token is the identity, and never fails.
  convert(text) {
    return text;
  },
};

export const INT = {
  name: 'int',
  convert(text) {
    return pyInt(text);
  },
};
// Facade mirroring the `argparse` module's public surface.

export { ArgumentParser, ArgumentError, ArgumentParserError } from './parser.mjs';
export { STR, INT } from './types.mjs';
export { formatUsage, formatHelp } from './formatter.mjs';
